import * as T from './assets/three.module.js';
export function createRig(scene){let rig=new T.Group();scene.add(rig);const root=new T.Bone();root.name='torso';rig.add(root);const list=[root],bones={};bones.torso=root;function add(name,parent,global){const b=new T.Bone();b.name=name;b.userData.rest=new T.Vector3(...global);const parentGlobal=parent.userData.rest||new T.Vector3();b.position.copy(b.userData.rest).sub(parentGlobal);parent.add(b);list.push(b);bones[name]=b;return b}root.userData.rest=new T.Vector3();for(const side of ['L','R']){const sign=side==='L'?1:-1;const sh=add('shoulder'+side,root,[sign*.16,1.405,-.025]);add('elbow'+side,sh,[sign*.225,1.11,-.02]);const hip=add('hip'+side,root,[sign*.08,.89,-.025]);const knee=add('knee'+side,hip,[sign*.08,.465,-.025]);add('ankle'+side,knee,[sign*.075,.09,-.025]);}rig.updateMatrixWorld(true);const skeleton=new T.Skeleton(list);const ids={};list.forEach((b,i)=>ids[b.name]=i);return {ids,skeleton,bones,rig};}
export function skinGeometry(g,p,ids){const pos=g.attributes.position,indices=new Uint16Array(pos.count*4),weights=new Float32Array(pos.count*4),center=new T.Vector3(...p.bounds[0]).add(new T.Vector3(...p.bounds[1])).multiplyScalar(.5),whole=['integumentary','sensory'].includes(p.system)&&p.vertexCount>2000;for(let i=0;i<pos.count;i++){const x=pos.getX(i),y=pos.getY(i),px=whole?x:center.x,py=whole?y:center.y,side=px>=0?'L':'R';let a=0,b=0,w=1;
 if(Math.abs(px)>.145&&py>.70&&py<1.445){if(y>1.365){a=0;b=ids['shoulder'+side];w=T.MathUtils.smoothstep(y,1.365,1.44);}else{a=ids['shoulder'+side];b=ids['elbow'+side];w=T.MathUtils.smoothstep(y,1.07,1.15);}}
 else if(py<(whole?.90:.84)&&Math.abs(px)<.205){if(y>.82){a=0;b=ids['hip'+side];w=T.MathUtils.smoothstep(y,.82,.9);}else if(y>.40){a=ids['hip'+side];b=ids['knee'+side];w=T.MathUtils.smoothstep(y,.43,.50);}else{a=ids['knee'+side];b=ids['ankle'+side];w=T.MathUtils.smoothstep(y,.075,.13);}}
 indices[i*4]=a;indices[i*4+1]=b;weights[i*4]=w;weights[i*4+1]=1-w;
 }g.setAttribute('skinIndex',new T.BufferAttribute(indices,4));g.setAttribute('skinWeight',new T.BufferAttribute(weights,4));return center;}
